illustrative_ports.atomic:
// In the consuming capability; illustrative only.
type GiftStore interface {
    Purchase(ctx context.Context, command GiftPurchase) (GiftReceipt, error)
}
// Receipt describes committed effects; SQL types stay in the adapter.

illustrative_ports.transaction_scope:
// Alternative only when the use case needs several scoped capabilities.
type GiftTransactions interface {
    WithinGift(ctx context.Context, work func(context.Context, GiftLedger, GiftInventory, GiftMessages) error) error
}
// The SQLite implementation BeginTx(ctx, nil)s once and supplies repositories
// bound to the same sqlc DBTX. Commit/rollback remain adapter-owned.

illustrative_ports.typed_delivery:
// Illustrative outbound contract, not a finalized API.
type DeliveryHandle string
type Delivery struct { Handle DeliveryHandle; Event Event }
type DeliveryQueue interface {
    Take(ctx context.Context, session SessionID) ([]Delivery, error)
    Complete(ctx context.Context, handles []DeliveryHandle, written bool) error
}
// Final design must preserve eligibility rechecks and response/write gates.
// Native codec maps typed Event to protocol.Packet outside business modules.
